function weblogin() {
  let so = source.key.split("#")[0]
  let ck = String(cookie.getKey(so, "jieqiUserInfo"));
    if (ck && ck != "") {
        java.toast("请不要重复登录，请先退出登录！")
        return false
    }
  try {
    java.startBrowserAwait(so, "登录")
  } catch (e) { java.toast(e) }

  ck = cookie.getKey(so, 'jieqiUserInfo')
  if (!ck || ck == "") {
     java.toast("未获取到登录凭据，登录失败")
     return false
  }
  let userInfo, user, header
  try {
     userInfo = org.jsoup.Jsoup.parse(java.ajax(so + "/user.php," + JSON.stringify({ method: "GET", headers: { "Cookie": ck }})))
     java.log(JSON.stringify(userInfo))
     user = userInfo.select(".user-name").text()
  } catch (e) { java.log(e) }
  java.toast("欢迎用户：" + user + "\n登录成功！")
  ck += ";night=1"
  header = JSON.stringify({
    "Referer": so,
    "User-Agent": "Mozilla/5.0 (Linux; Android 10; u) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/100.0.98.201 Mobile Safari/537.36",
    "Cookie": ck,
    "Accept-Language": "zh-CN,zh;q=0.9,en-US;q=0.8,en;q=0.7",
    "Accept": "*/*"
  })
  source.putLoginHeader(header)
  return true
}

function login() {}

function Out() {
  let host = source.key.split("#")[0]
  source.removeLoginHeader();
  java.toast("退出成功")
}

